import { jsPDF } from "jspdf";

// 세로 방향, mm 단위, A4 용지
const doc = new jsPDF({
  orientation: "portrait",
  unit: "mm",
  format: "a4",
});

doc.setFontSize(16);
doc.text("Report", 20, 20);

doc.setFontSize(11);
doc.text("Generated in the browser.", 20, 30);
doc.line(20, 34, 190, 34);

doc.addPage();
doc.text("Second page", 20, 20);

doc.save("report.pdf");
